import{_ as t,o,c as r,ag as s}from"./chunks/framework.em2JOrjF.js";const _=JSON.parse('{"title":"User Tools","description":"","frontmatter":{},"headers":[],"relativePath":"tools/users.md","filePath":"tools/users.md"}'),a={name:"tools/users.md"};function d(n,e,c,i,u,l){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="user-tools" tabindex="-1">User Tools <a class="header-anchor" href="#user-tools" aria-label="Permalink to &quot;User Tools&quot;">​</a></h1><hr><h2 id="add_user" tabindex="-1">add_user <a class="header-anchor" href="#add_user" aria-label="Permalink to &quot;add_user {#add_user}&quot;">​</a></h2><p>Create a new team member. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>03. Users</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>slack_user_id</code></td><td>✅</td><td>Must message the bot first for auto-detection</td></tr><tr><td><code>user_name</code></td><td>✅</td><td>Display name</td></tr><tr><td><code>role</code></td><td>✅</td><td><code>&quot;owner&quot;</code> | <code>&quot;manager&quot;</code> | <code>&quot;user&quot;</code></td></tr><tr><td><code>discipline_id</code></td><td></td><td>FK → <code>08. Disciplines.id</code></td></tr><tr><td><code>employment_type</code></td><td></td><td><code>&quot;fte&quot;</code> (default) | <code>&quot;contractor&quot;</code> | <code>&quot;vendor&quot;</code></td></tr><tr><td><code>hours_per_week</code></td><td></td><td>Float. Working hours per week. <strong>FTE</strong>: omit — defaults to 40. <strong>Contractor</strong>: required — VERA will ask if not provided. <strong>Vendor</strong>: omit — defaults to 40 (not used for capacity).</td></tr></tbody></table><hr><h2 id="list_users" tabindex="-1">list_users <a class="header-anchor" href="#list_users" aria-label="Permalink to &quot;list_users {#list_users}&quot;">​</a></h2><p>All active users with disciplines.</p><p><strong>Reads from</strong>: <code>03. Users</code>, <code>08. Disciplines</code></p><p>Inactive users appear with <code>(inactive)</code> next to their name.</p><hr><h2 id="update_user_role" tabindex="-1">update_user_role <a class="header-anchor" href="#update_user_role" aria-label="Permalink to &quot;update_user_role {#update_user_role}&quot;">​</a></h2><p>Change a user&#39;s permission role. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>03. Users</code> col D</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code> or <code>slack_user_id</code>, <code>new_role</code></p><hr><h2 id="rename_user" tabindex="-1">rename_user <a class="header-anchor" href="#rename_user" aria-label="Permalink to &quot;rename_user {#rename_user}&quot;">​</a></h2><p>Change a user&#39;s display name. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>03. Users</code> col C</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>current_name</code> or <code>slack_user_id</code>, <code>new_name</code></p><hr><h2 id="assign_pm" tabindex="-1">assign_pm <a class="header-anchor" href="#assign_pm" aria-label="Permalink to &quot;assign_pm {#assign_pm}&quot;">​</a></h2><p>Assign a project manager to a project. <strong>Owner only.</strong></p><p>This is a two-in-one operation:</p><ol><li>Promotes the user to <code>manager</code> role (if currently <code>user</code>)</li><li>Sets <code>pm_user_id</code> on the project</li></ol><p><strong>Updates</strong>: <code>02. Projects</code> col G, <code>03. Users</code> col D</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code>, <code>pm_name</code> or <code>pm_slack_id</code></p><blockquote><p>If the user hasn&#39;t messaged the bot yet, they won&#39;t be in the system. They need to send at least one message to be auto-registered before they can be assigned as PM.</p></blockquote><hr><h2 id="deactivate_user" tabindex="-1">deactivate_user <a class="header-anchor" href="#deactivate_user" aria-label="Permalink to &quot;deactivate_user {#deactivate_user}&quot;">​</a></h2><p>Mark a user as inactive. They cannot log time or take any actions. Historical entries are preserved. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>03. Users</code> col E (status → <code>&quot;inactive&quot;</code>)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code> or <code>slack_user_id</code></p><p>Natural language triggers: &quot;delete user&quot;, &quot;remove user&quot;, &quot;deactivate user&quot; — all map to this tool.</p><hr><h2 id="reactivate_user" tabindex="-1">reactivate_user <a class="header-anchor" href="#reactivate_user" aria-label="Permalink to &quot;reactivate_user {#reactivate_user}&quot;">​</a></h2><p>Restore an inactive user. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>03. Users</code> col E (status → <code>&quot;active&quot;</code>)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code> or <code>slack_user_id</code></p><p>Natural language triggers: &quot;reactivate&quot;, &quot;restore&quot;, &quot;re-enable&quot;</p><hr><h2 id="ensure_user" tabindex="-1">ensure_user <a class="header-anchor" href="#ensure_user" aria-label="Permalink to &quot;ensure_user {#ensure_user}&quot;">​</a></h2><p>Internal tool — auto-creates a user record if one doesn&#39;t exist for the given Slack ID. Called automatically when a new person messages the bot. Creates with <code>role = &quot;user&quot;</code> and <code>employment_type = &quot;fte&quot;</code>.</p><hr><h2 id="list_disciplines" tabindex="-1">list_disciplines <a class="header-anchor" href="#list_disciplines" aria-label="Permalink to &quot;list_disciplines {#list_disciplines}&quot;">​</a></h2><p>All functional discipline categories.</p><p><strong>Reads from</strong>: <code>08. Disciplines</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><hr><h2 id="add_discipline" tabindex="-1">add_discipline <a class="header-anchor" href="#add_discipline" aria-label="Permalink to &quot;add_discipline {#add_discipline}&quot;">​</a></h2><p>Create a new functional discipline category. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>08. Disciplines</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>name</code></p><blockquote><p>The words &quot;Designer,&quot; &quot;Developer,&quot; &quot;Project Manager&quot; may refer to a person name or a discipline. VERA confirms before acting when the context is ambiguous.</p></blockquote><hr><h2 id="get_project_assignments" tabindex="-1">get_project_assignments <a class="header-anchor" href="#get_project_assignments" aria-label="Permalink to &quot;get_project_assignments {#get_project_assignments}&quot;">​</a></h2><p>Who is allocated to a project. <strong>Manager/Owner.</strong></p><p>Shared with <a href="/vera-docs/tools/allocations.html#get_project_assignments">Envelope Tools</a> — documented there.</p>',60)])])}const h=t(a,[["render",d]]);export{_ as __pageData,h as default};
